package com.example.employeeleave;
import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/employees") @org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')") public class EmployeeController {private final UserRepository users;private final PasswordEncoder encoder;public EmployeeController(UserRepository u,PasswordEncoder e){users=u;encoder=e;}
 @GetMapping public List<Map<String,Object>> all(){return users.findAll().stream().map(this::view).toList();}
 @GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id){return view(users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found")));}
 @PostMapping public ResponseEntity<?> create(@RequestBody Body b){if(b.name==null||b.name.isBlank()||b.email==null||b.email.isBlank()||b.password==null||b.password.length()<6)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Name, email and password (at least 6 characters) are required");if(users.existsByEmailIgnoreCase(b.email.trim()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");User u=new User(b.name.trim(),b.email.trim().toLowerCase(),encoder.encode(b.password));u.setRole(role(b.role));return ResponseEntity.status(HttpStatus.CREATED).body(view(users.save(u)));}
 @PutMapping("/{id}") public Map<String,Object> update(@PathVariable Long id,@RequestBody Body b){User u=users.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found"));if(b.name!=null&&!b.name.isBlank())u.setName(b.name.trim());if(b.email!=null&&!b.email.isBlank())u.setEmail(b.email.trim().toLowerCase());if(b.role!=null)u.setRole(role(b.role));if(b.password!=null&&!b.password.isBlank()){if(b.password.length()<6)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Password must be at least 6 characters");u.setPassword(encoder.encode(b.password));}return view(users.save(u));}
 @DeleteMapping("/{id}") public ResponseEntity<?> delete(@PathVariable Long id){if(!users.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"User not found");users.deleteById(id);return ResponseEntity.noContent().build();}
 private String role(String r){String v=r==null?"EMPLOYEE":r.trim().toUpperCase();if(!List.of("EMPLOYEE","MANAGER","ADMIN").contains(v))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid role");return v;}
 private Map<String,Object> view(User u){return Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole(),"isActive",true);}
 public static class Body {public String name,email,password,role;}
}
